<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
if(isset($_SESSION['admin'])&&time()-(int)($_SESSION['last_seen']??0)>1800)unset($_SESSION['admin']);
if(empty($_SESSION['admin'])){http_response_code(403);exit('Inicia sesión.');}$_SESSION['last_seen']=time();
$appRoot=dirname((new ReflectionFunction('db'))->getFileName());require_once $appRoot.'/OperatingFinanceService.php';require_once $appRoot.'/CostEvidenceService.php';
$evidence=new CostEvidenceService(db(),private_storage_path('operating-cost-evidence'));$evidenceReady=$evidence->ready();
$error='';$finance=new OperatingFinanceService(db());$available=$finance->ready();
if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf();if(!$available)throw new RuntimeException('Falta aplicar la migración 031 en Base de datos.');$action=$_POST['action']??'';if($action==='add')$evidence->create($finance,$_POST,(string)($config['admin_user']??'admin'),$_FILES['evidence']??[]);elseif($action==='attach')$evidence->attach((int)($_POST['cost_id']??0),(string)($config['admin_user']??'admin'),$_FILES['evidence']??[]);elseif($action==='void')$finance->voidCost((int)($_POST['id']??0),(string)($_POST['reason']??''));elseif($action==='review')$finance->reviewCancellation((int)($_POST['id']??0),(string)($_POST['note']??''));else throw new RuntimeException('Acción no permitida.');header('Location: costos.php?guardado=1',true,303);exit;}catch(Throwable $e){$error=$e instanceof PDOException?'No se pudo guardar. Revisa la estructura de Base de datos.':$e->getMessage();http_response_code(400);}}
$destinations=db()->query("SELECT d.id,t.display_name FROM destinations d JOIN destination_translations t ON t.destination_id=d.id AND t.locale='es' ORDER BY t.display_name")->fetchAll();
$costs=$available?db()->query('SELECT c.*,t.display_name AS destination_name FROM operating_costs c LEFT JOIN destination_translations t ON t.destination_id=c.destination_id AND t.locale="es" ORDER BY c.cost_date DESC,c.id DESC LIMIT 200')->fetchAll():[];
$requests=$available?db()->query('SELECT r.*,t.display_name AS business_name FROM subscription_cancellation_requests r JOIN business_translations t ON t.business_id=r.business_id AND t.locale="es" ORDER BY r.created_at DESC LIMIT 200')->fetchAll():[];
$costEvidence=[];
if($evidenceReady&&$costs){$ids=array_column($costs,'id');$q=db()->prepare('SELECT id,cost_id,original_name,file_size FROM operating_cost_evidence WHERE cost_id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY id');$q->execute($ids);foreach($q as $file)$costEvidence[$file['cost_id']][]=$file;}
function cost_file_picker(string $id,bool $required=false):void { ?>
<div class="cost-upload"><label for="<?=esc($id)?>">Factura, recibo o pantallazo<?=$required?'':' (opcional)'?></label><div class="cost-upload-control"><label class="cost-upload-button"><span>Elegir soporte</span><input id="<?=esc($id)?>" type="file" name="evidence" accept="application/pdf,image/jpeg,image/png,image/webp" data-cost-file aria-describedby="<?=esc($id)?>-name <?=esc($id)?>-help" <?=$required?'required':''?>></label><span id="<?=esc($id)?>-name" data-cost-filename role="status" aria-live="polite">Ningún archivo seleccionado</span></div><small id="<?=esc($id)?>-help">PDF, JPG, PNG o WebP · Máximo 8 MB por archivo · Almacenamiento privado.</small></div>
<?php }
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Costos y solicitudes de cancelación | Administración</title><link rel="stylesheet" href="../assets/style.css"><link rel="stylesheet" href="../assets/admin.css?v=finance-evidence-20261016"></head><body><main class="wrap admin-page cost-admin"><h1>Costos y solicitudes de cancelación</h1><?php require __DIR__.'/_navigation.php'; ?><?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?><?php if(isset($_GET['guardado'])):?><p class="notice" role="status">Registro guardado.</p><?php endif ?>
<?php if(!$available):?><p class="notice">Falta aplicar la migración 031 desde <a href="base-datos.php">Base de datos</a>. No se crean tablas automáticamente.</p><?php else:?>
<section class="admin-system"><h2>Registrar un gasto realizado</h2><p>Registra cada gasto una sola vez y usa su fecha real. Puedes asociarlo a un lugar o dejarlo como costo general. Es un control operativo, no contabilidad fiscal ni conciliación bancaria.</p><form method="post" enctype="multipart/form-data" class="cost-form cost-create-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="add"><label>Fecha del gasto<input type="date" name="cost_date" max="<?=esc(gmdate('Y-m-d'))?>" required></label><label>Categoría<select name="category" required><?php foreach(OperatingFinanceService::CATEGORIES as $code=>$label):?><option value="<?=esc($code)?>"><?=esc($label)?></option><?php endforeach ?></select></label><label>Importe COP · sin separadores de miles<input type="number" name="amount_cop" step="0.01" min="0.01" max="999999999999.99" required></label><label>Lugar<select name="destination_id"><option value="">Costo general del portal</option><?php foreach($destinations as $destination):?><option value="<?=esc($destination['id'])?>"><?=esc($destination['display_name'])?></option><?php endforeach ?></select></label><label class="cost-wide">Descripción<textarea name="description" maxlength="500" rows="3" required placeholder="Por ejemplo: alojamiento durante la visita de trabajo al lugar"></textarea></label><?php if($evidenceReady):?><div class="cost-wide"><?php cost_file_picker('new-cost-evidence'); ?></div><?php else:?><p class="notice cost-wide">Adjuntos pendientes de aplicar la migración 032.</p><?php endif ?><div class="cost-form-actions cost-wide"><button class="pill">Guardar gasto y soporte</button><span>El soporte es opcional. Puedes agregar más documentos después.</span></div></form></section>
<section class="admin-system"><h2>Últimos 200 gastos</h2><p>Las correcciones se hacen anulando el registro y creando uno correcto; se conserva el registro original.</p><div class="health-table"><table><thead><tr><th>Fecha / descripción</th><th>Categoría / lugar</th><th>Importe</th><th>Soportes privados</th><th>Estado / corrección</th></tr></thead><tbody><?php foreach($costs as $cost):?><tr><td><?=esc($cost['cost_date'])?><br><?=esc($cost['description'])?></td><td><?=esc(OperatingFinanceService::CATEGORIES[$cost['category']]??$cost['category'])?><br><?=esc($cost['destination_name']??'General')?></td><td><?=esc(number_format((float)$cost['amount_cop'],2,',','.'))?> COP</td><td><div class="cost-evidence-list"><?php foreach($costEvidence[$cost['id']]??[] as $file):?><a href="soporte-gasto.php?id=<?=esc($file['id'])?>">Descargar <?=esc($file['original_name'])?></a><?php endforeach ?><?php if(empty($costEvidence[$cost['id']])):?><span>Sin soporte adjunto</span><?php endif ?></div><?php if($evidenceReady):?><details class="cost-details"><summary>Agregar soporte</summary><form method="post" enctype="multipart/form-data" class="cost-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="attach"><input type="hidden" name="cost_id" value="<?=esc($cost['id'])?>"><?php cost_file_picker('cost-evidence-'.(int)$cost['id'],true); ?><button class="pill light">Guardar soporte</button></form></details><?php endif ?></td><td><?php if($cost['voided_at']):?>Anulado: <?=esc($cost['void_reason'])?><?php else:?><details><summary>Anular registro</summary><form method="post" class="cost-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="void"><input type="hidden" name="id" value="<?=esc($cost['id'])?>"><label>Motivo<input name="reason" maxlength="500" required></label><button class="pill light">Anular gasto registrado</button></form></details><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="admin-system"><h2>Solicitudes de cancelación / no renovación</h2><p>Solicitudes de los responsables de negocios. Atender una solicitud registra la gestión; no revoca automáticamente el período pagado, no devuelve dinero y no cancela pagos en un proveedor externo. No equivale a una tasa de abandono.</p><?php if(!$requests):?><p>Sin solicitudes.</p><?php endif ?><?php foreach($requests as $request):?><article class="cost-cancellation"><h3><?=esc($request['business_name'])?></h3><p><?=esc(OperatingFinanceService::REASONS[$request['reason_code']]??$request['reason_code'])?> · <?=esc($request['created_at'])?></p><p><?=esc($request['reason_text'])?></p><?php if($request['status']==='pending'):?><form method="post" class="cost-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?=esc($request['id'])?>"><label>Resultado de la atención · visible para el negocio<textarea name="note" maxlength="1000" required></textarea></label><button class="pill">Registrar atención</button></form><?php else:?><p>Atendida: <?=esc($request['review_note'])?></p><?php endif ?></article><?php endforeach ?></section><?php endif ?><script src="../assets/admin-costs.js?v=1" defer></script></main></body></html>
